 void render(){grid.removeAllViews();rail.removeAllViews();rowNumber=0;if(screen==0){home();return;}String q=search.getText().toString().toLowerCase(Locale.ROOT);String last="";LinearLayout row=null;for(App app:apps){if(!app.name.toLowerCase(Locale.ROOT).contains(q))continue;String letter=app.name.isEmpty()?"#":app.name.substring(0,1).toUpperCase(Locale.ROOT);if(!letter.equals(last)){if(row!=null&&row.getChildCount()==1)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));heading(letter);View anchor=grid.getChildAt(grid.getChildCount()-1);TextView jump=text(letter,11,headingInk());rail.addView(jump,new LinearLayout.LayoutParams(-1,dp(26)));jump.setOnClickListener(v->{for(int z=0;z<rail.getChildCount();z++)((TextView)rail.getChildAt(z)).setTextColor(headingInk());jump.setTextColor(accent());scroll.smoothScrollTo(0,anchor.getTop());});last=letter;row=null;}if(row==null||row.getChildCount()==2){row=new LinearLayout(this);grid.addView(row);}appCard(row,app,false);}if(row!=null&&row.getChildCount()==1)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
